/* Atlas explorer: georeferenced satellite tiles, editable schematic routes and offline world map. */
const atlasText={ru:{routes:'Маршруты',world:'Карта мира',eyebrow:'Места, которые становятся историями',title:'Ближе к <em>открытиям.</em>',intro:'Выберите маршрут. Загляните за следующий поворот.',satellite:'Спутник',terrain:'Рельеф',diagram:'Схема',demo:'Демо-маршрут',stops:'точки',distance:'Между точками',points:'Точки маршрута',selected:'Ваша следующая остановка',add:'Добавить точку',fit:'Весь маршрут',zoomIn:'Приблизить',zoomOut:'Отдалить',zoom:'Масштаб',favorite:'Сохранить маршрут',unfavorite:'Убрать из избранного',favoriteSaved:'Маршрут сохранён в избранное',favoriteRemoved:'Маршрут убран из избранного',fullscreen:'На весь экран',exitFullscreen:'Закрыть полный экран',mapLabel:'Интерактивная карта маршрута',note:'Пунктир соединяет точки по прямой: это схема, а не навигационный трек.',online:'Спутниковый слой загружается из сети.',tileError:'Слой карты недоступен. Попробуйте «Рельеф» или «Схему».',tap:'Нажмите на карту, чтобы поставить точку',newPoint:'Новая точка маршрута',pointTitle:'Название места',pointPlaceholder:'Например, место для пикника',pointNotes:'Что здесь интересного?',pointAdded:'Точка добавлена в маршрут',remove:'Удалить мою точку',removed:'Точка удалена',custom:'Ваша точка',walk:'Пешая прогулка',preview:'Исследовать маршрут',back:'К маршруту',km:'км',step:'Остановка',schemaHint:'Схема без спутниковых снимков',leafletError:'Не удалось загрузить интерактивную карту. Попробуйте карту мира.',choose:'Выберите маршрут',saved:'В избранном',help:'Перемещайте карту, приближайте двумя пальцами и нажимайте на отметки.'},en:{routes:'Routes',world:'World map',eyebrow:'Places that turn into stories',title:'A little closer to <em>discovery.</em>',intro:'Choose a route. See what is around the next bend.',satellite:'Satellite',terrain:'Terrain',diagram:'Diagram',demo:'Demo route',stops:'stops',distance:'Between points',points:'Along the way',selected:'Your next little discovery',add:'Add a stop',fit:'Fit route',zoomIn:'Zoom in',zoomOut:'Zoom out',zoom:'Zoom',favorite:'Save route',unfavorite:'Remove favorite',favoriteSaved:'Route saved to favorites',favoriteRemoved:'Route removed from favorites',fullscreen:'Full screen',exitFullscreen:'Exit full screen',mapLabel:'Interactive route map',note:'The dotted line connects stops directly. This is a diagram, not a navigation track.',online:'Satellite imagery needs an internet connection.',tileError:'Map tiles are unavailable. Try Terrain or Diagram.',tap:'Tap the map to add a stop',newPoint:'A new stop',pointTitle:'Place name',pointPlaceholder:'For example, a picnic spot',pointNotes:'What makes this place special?',pointAdded:'Stop added to your route',remove:'Remove my stop',removed:'Stop removed',custom:'Your stop',walk:'Walking route',preview:'Explore the route',back:'Back to the route',km:'km',step:'Stop',schemaHint:'Diagram without satellite imagery',leafletError:'The interactive map could not load. Try the world map.',choose:'Choose a route',saved:'Saved',help:'Drag the map, pinch to zoom and select a pin.'}};
const at=k=>atlasText[lang][k]||k;
const ATLAS_ROUTES=[{id:'skye',name:{ru:'Тропа над облаками',en:'A trail above the clouds'},location:{ru:'Остров Скай, Шотландия',en:'Isle of Skye, Scotland'},image:'forest',description:{ru:'Зелёные склоны, туман в долине и горизонт, который хочется разглядывать без спешки. Соберите свой маршрут из маленьких открытий.',en:'Green slopes, mist in the valley and a horizon worth slowing down for. Build your own route from little discoveries.'},points:[{lat:57.6288,lon:-6.2929,name:{ru:'Начало пути',en:'The beginning'},notes:{ru:'Проверьте свои планы перед прогулкой и выберите первую остановку.',en:'Check your plans and choose your first stop.'},icon:'pin'},{lat:57.6332,lon:-6.2868,name:{ru:'Зелёная долина',en:'The green valley'},notes:{ru:'Пауза, чтобы оглядеться вокруг и сделать пару кадров.',en:'A moment to look around and capture a few memories.'},icon:'heart'},{lat:57.6378,lon:-6.2815,name:{ru:'Выше облаков',en:'Above the clouds'},notes:{ru:'Добавьте сюда свои заметки о месте и впечатления от поездки.',en:'Add your own notes and memories from the journey.'},icon:'map'},{lat:57.6337,lon:-6.2721,name:{ru:'Новый горизонт',en:'A new horizon'},notes:{ru:'Последняя точка схемы — или начало нового приключения.',en:'The final stop in this diagram, or the beginning of another adventure.'},icon:'check'}]},{id:'altai',name:{ru:'Там, где дышат горы',en:'Where the mountains breathe'},location:{ru:'Алтай, Россия',en:'Altai, Russia'},image:'mountains',description:{ru:'Река, лес и горы на горизонте. Сохраните места, к которым хочется вернуться, и соедините их в свою историю.',en:'A river, a forest and mountains on the horizon. Save the places you want to return to and connect them into your own story.'},points:[{lat:50.091,lon:86.45,name:{ru:'У реки',en:'By the river'},notes:{ru:'Первая точка демонстрационной схемы. Здесь можно начать свой план.',en:'The first point of this sample diagram. Start your own plan here.'},icon:'pin'},{lat:50.078,lon:86.469,name:{ru:'Лесная остановка',en:'A forest stop'},notes:{ru:'Время остановиться и записать маленькие открытия.',en:'Time to pause and write down a little discovery.'},icon:'heart'},{lat:50.061,lon:86.48,name:{ru:'Горизонт',en:'The horizon'},notes:{ru:'Отметьте здесь любимый вид или место будущей прогулки.',en:'Mark a favorite view or the place for a future walk.'},icon:'map'},{lat:50.051,lon:86.506,name:{ru:'Следующая глава',en:'The next chapter'},notes:{ru:'Добавляйте собственные точки прямо на карте.',en:'Add your own stops directly on the map.'},icon:'check'}]},{id:'coast',name:{ru:'Навстречу морю',en:'Towards the sea'},location:{ru:'Лигурия, Италия',en:'Liguria, Italy'},image:'italy',description:{ru:'Маленькие города, морской воздух и прогулка без спешки. У каждого поворота — свой повод остановиться.',en:'Little towns, sea air and an unhurried walk. Every bend is another reason to pause.'},points:[{lat:44.1197,lon:9.7089,name:{ru:'Утро у моря',en:'Morning by the sea'},notes:{ru:'Начните новую историю с любимого места на побережье.',en:'Start a new story at a favorite spot on the coast.'},icon:'pin'},{lat:44.1231,lon:9.7123,name:{ru:'Тихая улица',en:'A quiet street'},notes:{ru:'Сохраните небольшое открытие по пути.',en:'Save a little discovery along the way.'},icon:'heart'},{lat:44.126,lon:9.7182,name:{ru:'Панорама',en:'The panorama'},notes:{ru:'Место для фотографий и заметок о путешествии.',en:'A place for photographs and travel notes.'},icon:'map'},{lat:44.13,lon:9.722,name:{ru:'Дальше — больше',en:'More to discover'},notes:{ru:'Продолжите маршрут своими точками.',en:'Continue the route with your own stops.'},icon:'check'}]}];
let atlasMode='routes',atlasRouteId='skye',atlasSelected=0,atlasLayer='satellite',atlasMap=null,atlasTileLayer=null,atlasPolyline=null,atlasMarkers=[],atlasAdding=false,atlasResizeObserver=null,atlasTileGeneration=0;
function activeAtlasRoute(){return ATLAS_ROUTES.find(r=>r.id===atlasRouteId)||ATLAS_ROUTES[0]}
function routePoints(){const own=data.atlasRoutePoints?.[atlasRouteId];return [...activeAtlasRoute().points,...(Array.isArray(own)?own.filter(p=>Number.isFinite(p.lat)&&Number.isFinite(p.lon)&&Math.abs(p.lat)<=85&&Math.abs(p.lon)<=180&&typeof p.name==='string').map(p=>({...p,custom:true})):[])]}
function routeDistance(){const pts=routePoints();let sum=0;for(let i=1;i<pts.length;i++){const a=pts[i-1],b=pts[i],rad=Math.PI/180,dl=(b.lat-a.lat)*rad,dn=(b.lon-a.lon)*rad;const h=Math.sin(dl/2)**2+Math.cos(a.lat*rad)*Math.cos(b.lat*rad)*Math.sin(dn/2)**2;sum+=6371*2*Math.atan2(Math.sqrt(h),Math.sqrt(1-h))}return sum.toLocaleString(lang==='ru'?'ru-RU':'en-GB',{maximumFractionDigits:1})}
function atlasModeControl(){return `<div class="atlas-mode-bar"><div class="segmented atlas-mode" role="group" aria-label="${t('atlas')}"><button data-atlas-mode="routes" class="${atlasMode==='routes'?'active':''}" aria-pressed="${atlasMode==='routes'}">${icon('pin')}${at('routes')}</button><button data-atlas-mode="world" class="${atlasMode==='world'?'active':''}" aria-pressed="${atlasMode==='world'}">${icon('map')}${at('world')}</button></div></div>`}
function atlas(){if(atlasMode==='world')return atlasWorld().replace('<div class="page">','<div class="page atlas-page">'+atlasModeControl());return atlasExperience()}
function atlasExperience(){const r=activeAtlasRoute();return `<div class="page atlas-page">${atlasModeControl()}<div class="section-head atlas-heading"><div><span class="eyebrow">${at('eyebrow')}</span><h1>${at('title')}</h1><p>${at('intro')}</p></div><button class="text-button" data-action="create-place">${icon('plus')}${t('addPlace')}</button></div><div class="atlas-route-options" role="group" aria-label="${at('choose')}">${ATLAS_ROUTES.map(route=>`<button data-atlas-route="${route.id}" class="atlas-route-option ${r.id===route.id?'active':''}" aria-pressed="${r.id===route.id}"><img src="assets/${route.image}.jpg" alt=""><span>${esc(local(route.location))}</span></button>`).join('')}</div><section class="route-explorer" id="route-explorer" aria-label="${at('mapLabel')}"><div id="route-map" class="route-map" tabindex="0" aria-label="${at('mapLabel')}"></div><div class="route-vignette" aria-hidden="true"></div><div class="route-topbar"><span class="route-live-label">${icon('pin')}${at('demo')}</span><div class="route-layer-control" role="group" aria-label="${at('mapLabel')}">${['satellite','terrain','diagram'].map(k=>`<button data-atlas-layer="${k}" class="${atlasLayer===k?'active':''}" aria-pressed="${atlasLayer===k}">${at(k)}</button>`).join('')}</div></div><aside class="route-info" id="route-info">${atlasRouteInfo()}</aside><div class="route-point-toast" id="route-map-status" role="status"></div><div class="route-controls"><button data-route-control="fit" aria-label="${at('fit')}" title="${at('fit')}">${icon('map')}</button><span class="route-control-divider"></span><button data-route-control="out" aria-label="${at('zoomOut')}">−</button><input type="range" id="route-zoom" min="5" max="17" step="1" value="13" aria-label="${at('zoom')}"><button data-route-control="in" aria-label="${at('zoomIn')}">+</button><button data-route-control="fullscreen" aria-label="${at('fullscreen')}" title="${at('fullscreen')}"><svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 9V4h5m6 0h5v5M4 15v5h5m6 0h5v-5"/></svg></button></div></section><div class="atlas-below"><p>${at('note')}</p><span>${at('online')}</span></div><section class="atlas-saved-places"><div class="section-head"><div><span class="eyebrow">${t('myPlaces')}</span><h2>${t('atlas')}</h2></div><button class="text-button" data-atlas-mode="world">${at('world')}${icon('map')}</button></div><div class="atlas-place-strip">${data.places.map(p=>`<button class="atlas-place-pill" data-place="${esc(p.id)}">${icon('pin')}<span>${esc(lang==='en'?p.cityEn||p.city:p.city)}<small>${esc(cn(p.country))}</small></span></button>`).join('')||`<button class="ghost" data-action="create-place">${t('addPlace')}</button>`}</div></section>${footer()}</div>`}
function atlasRouteInfo(){const r=activeAtlasRoute(),points=routePoints(),p=points[atlasSelected]||points[0],favorite=data.atlasFavorites?.includes(r.id);return `<div class="route-info-eyebrow"><span class="eyebrow">travelsplit · ${at('routes')}</span><button class="route-heart ${favorite?'saved':''}" data-route-control="favorite" aria-label="${at(favorite?'unfavorite':'favorite')}" aria-pressed="${!!favorite}">${icon('heart')}</button></div><h2>${esc(local(r.name))}</h2><p class="route-location">${icon('pin')}${esc(local(r.location))}</p><div class="route-facts"><div><span>${at('distance')}</span><strong>${routeDistance()} <small>${at('km')}</small></strong></div><div><span>${at('points')}</span><strong>${String(points.length).padStart(2,'0')}</strong></div></div><p class="route-intro">${esc(local(r.description))}</p><div class="route-stop-heading"><span class="eyebrow">${at('points')}</span><span>${String(atlasSelected+1).padStart(2,'0')} / ${String(points.length).padStart(2,'0')}</span></div><div class="route-stop-list">${points.map((point,i)=>`<button class="route-stop ${i===atlasSelected?'active':''}" data-atlas-stop="${i}" aria-pressed="${i===atlasSelected}"><span class="route-stop-number">${i===atlasSelected?icon(point.icon||'pin'):String(i+1).padStart(2,'0')}</span><span>${esc(local(point.name))}${point.custom?`<small>${at('custom')}</small>`:''}</span>${i===atlasSelected?'<i></i>':''}</button>`).join('')}</div><div class="route-selected-note"><span>${at('selected')}</span><p>${esc(local(p.notes)||'')}</p>${p.custom?`<button class="text-button danger" data-remove-route-stop="${atlasSelected}">${at('remove')}</button>`:''}</div><button class="route-add" data-route-control="add">${icon('plus')}${atlasAdding?at('tap'):at('add')}</button>`}
function disposeAtlasMap(){if(atlasResizeObserver){atlasResizeObserver.disconnect();atlasResizeObserver=null}if(atlasMap){atlasMap.remove();atlasMap=null}atlasTileLayer=null;atlasMarkers=[];atlasAdding=false;atlasTileGeneration++}
function mountAtlas(){if(atlasMode==='world'){drawMap();return}const container=$('#route-map');if(!container)return;if(typeof L==='undefined'){container.innerHTML=`<div class="map-loading">${at('leafletError')}</div>`;return}atlasMap=L.map(container,{zoomControl:false,scrollWheelZoom:false,minZoom:5,maxZoom:17,attributionControl:true,zoomSnap:1});L.control.scale({position:'bottomright',imperial:false}).addTo(atlasMap);atlasMap.on('click',e=>{if(atlasAdding)openAtlasPointForm(e.latlng)});atlasMap.on('zoomend',()=>{const slider=$('#route-zoom');if(slider)slider.value=atlasMap.getZoom()});setAtlasLayer(atlasLayer);paintRoute();fitAtlasRoute();if(typeof ResizeObserver!=='undefined'){atlasResizeObserver=new ResizeObserver(()=>{if(atlasMap){atlasMap.invalidateSize({pan:false})}});atlasResizeObserver.observe(container)}}
function setAtlasLayer(layer){atlasLayer=layer;const map=atlasMap;if(!map)return;const gen=++atlasTileGeneration;if(atlasTileLayer){map.removeLayer(atlasTileLayer);atlasTileLayer=null}$('#route-map').classList.toggle('diagram',layer==='diagram');document.querySelectorAll('[data-atlas-layer]').forEach(b=>{b.classList.toggle('active',b.dataset.atlasLayer===layer);b.setAttribute('aria-pressed',String(b.dataset.atlasLayer===layer))});const status=$('#route-map-status');if(status){status.textContent=layer==='diagram'?at('schemaHint'):'';status.classList.toggle('visible',layer==='diagram')}if(layer==='diagram')return;const url=layer==='terrain'?'https://services.arcgisonline.com/ArcGIS/rest/services/World_Topo_Map/MapServer/tile/{z}/{y}/{x}':'https://services.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}';const attribution=layer==='terrain'?'Tiles © Esri — Esri, HERE, Garmin, FAO, NOAA, USGS, OpenStreetMap contributors, GIS User Community':'Tiles © Esri — Vantor, Earthstar Geographics, GIS User Community';atlasTileLayer=L.tileLayer(url,{maxZoom:17,attribution,keepBuffer:1,detectRetina:false}).addTo(map);let failed=0,loaded=0;atlasTileLayer.on('tileerror',()=>{if(gen!==atlasTileGeneration)return;if(++failed>=3&&!loaded&&status){status.textContent=at('tileError');status.classList.add('visible')}});atlasTileLayer.on('tileload',()=>{if(gen!==atlasTileGeneration)return;loaded++;if(status&&!atlasAdding){status.classList.remove('visible')}})}
function paintRoute(){if(!atlasMap)return;atlasMarkers.forEach(m=>m.remove());atlasMarkers=[];if(atlasPolyline)atlasPolyline.remove();const points=routePoints(),positions=points.map(p=>[p.lat,p.lon]);atlasPolyline=L.featureGroup([L.polyline(positions,{color:'#14251b',weight:7,opacity:.55,interactive:false}),L.polyline(positions,{color:'#f4f4ce',weight:4,opacity:1,dashArray:'1 11',lineCap:'round',interactive:false})]).addTo(atlasMap);points.forEach((p,i)=>{const marker=L.marker([p.lat,p.lon],{icon:L.divIcon({className:'route-marker-wrap',html:`<button class="route-pin ${i===atlasSelected?'active':''}" data-atlas-stop="${i}" aria-label="${esc(local(p.name))}">${icon(p.icon||'pin')}</button>`,iconSize:[42,50],iconAnchor:[21,48],popupAnchor:[0,-47]}),keyboard:false,zIndexOffset:i===atlasSelected?1000:0}).addTo(atlasMap);marker.on('click',()=>{if(!atlasAdding)selectAtlasStop(i,false)});atlasMarkers.push(marker)});const p=points[atlasSelected]||points[0];atlasMarkers[atlasSelected]?.bindPopup(`<span class="route-popup-kicker">${at('step')} ${String(atlasSelected+1).padStart(2,'0')}</span><strong>${esc(local(p.name))}</strong><p>${esc(local(p.notes)||'')}</p>`,{className:'route-popup',autoPan:false,closeButton:false,maxWidth:240,minWidth:180}).openPopup()}
function updateAtlasInfo(){if($('#route-info'))$('#route-info').innerHTML=atlasRouteInfo()}
function selectAtlasStop(index,pan=true){const pts=routePoints();if(!Number.isInteger(index)||index<0||index>=pts.length)return;atlasSelected=index;updateAtlasInfo();paintRoute();if(pan&&atlasMap){const p=pts[index],wide=window.innerWidth>800;atlasMap.panTo([p.lat,p.lon],{animate:!window.matchMedia('(prefers-reduced-motion: reduce)').matches});if(wide)atlasMap.panBy([-145,35],{animate:false});else atlasMap.panBy([0,80],{animate:false})}}
function fitAtlasRoute(){if(!atlasMap)return;const pts=routePoints().map(p=>[p.lat,p.lon]),wide=window.innerWidth>800;atlasMap.fitBounds(L.latLngBounds(pts),{paddingTopLeft:wide?[360,130]:[55,155],paddingBottomRight:wide?[110,105]:[55,300],maxZoom:15,animate:false});const slider=$('#route-zoom');if(slider)slider.value=atlasMap.getZoom()}
function openAtlasPointForm(latlng){atlasAdding=false;$('#route-explorer')?.classList.remove('adding-stop');$('#route-map-status')?.classList.remove('visible');updateAtlasInfo();openModal(at('routes'),`<h2>${at('newPoint')}</h2><form id="atlas-point-form" data-lat="${latlng.lat}" data-lon="${latlng.lng}" data-route="${activeAtlasRoute().id}"><div class="form-grid">${field(at('pointTitle'),'name',{required:true,full:true,placeholder:at('pointPlaceholder')})}<label class="field full">${at('pointNotes')}<textarea name="notes" maxlength="2000" placeholder="${t('optional')}"></textarea></label></div><p class="form-note">${latlng.lat.toFixed(5)}, ${latlng.lng.toFixed(5)}</p>${formActions()}</form>`)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-atlas-mode],[data-atlas-route],[data-atlas-layer],[data-atlas-stop],[data-route-control],[data-remove-route-stop]');if(!b)return;e.stopImmediatePropagation();if(b.dataset.atlasMode){atlasMode=b.dataset.atlasMode;render();return}if(b.dataset.atlasRoute){atlasRouteId=b.dataset.atlasRoute;atlasSelected=0;render();return}if(b.dataset.atlasLayer){setAtlasLayer(b.dataset.atlasLayer);return}if(b.dataset.atlasStop!==undefined){selectAtlasStop(Number(b.dataset.atlasStop));return}if(b.dataset.removeRouteStop!==undefined){const ownIndex=Number(b.dataset.removeRouteStop)-activeAtlasRoute().points.length;if(ownIndex>=0){data.atlasRoutePoints[atlasRouteId].splice(ownIndex,1);atlasSelected=0;persist();updateAtlasInfo();paintRoute();fitAtlasRoute();toast(at('removed'))}return}const action=b.dataset.routeControl;if(action==='in')atlasMap?.zoomIn();if(action==='out')atlasMap?.zoomOut();if(action==='fit')fitAtlasRoute();if(action==='favorite'){const saved=new Set(Array.isArray(data.atlasFavorites)?data.atlasFavorites:[]);saved.has(atlasRouteId)?saved.delete(atlasRouteId):saved.add(atlasRouteId);data.atlasFavorites=[...saved];persist();updateAtlasInfo();toast(at(saved.has(atlasRouteId)?'favoriteSaved':'favoriteRemoved'))}if(action==='add'){atlasAdding=!atlasAdding;$('#route-explorer')?.classList.toggle('adding-stop',atlasAdding);const status=$('#route-map-status');if(status){status.textContent=at('tap');status.classList.toggle('visible',atlasAdding)}updateAtlasInfo()}if(action==='fullscreen'){const el=$('#route-explorer');if(document.fullscreenElement){document.exitFullscreen?.().catch(()=>{})}else if(el?.requestFullscreen){el.requestFullscreen().catch(()=>toast(at('help')))}else{el?.classList.toggle('expanded');atlasMap?.invalidateSize()}}},true);
document.addEventListener('input',e=>{if(e.target.id==='route-zoom'&&atlasMap)atlasMap.setZoom(+e.target.value)});
document.addEventListener('submit',e=>{const f=e.target;if(f.id!=='atlas-point-form')return;e.preventDefault();e.stopImmediatePropagation();const v=Object.fromEntries(new FormData(f));if(!v.name.trim())return;const lat=+f.dataset.lat,lon=+f.dataset.lon;if(!Number.isFinite(lat)||!Number.isFinite(lon)||Math.abs(lat)>85||Math.abs(lon)>180)return;data.atlasRoutePoints??={};data.atlasRoutePoints[f.dataset.route]??=[];data.atlasRoutePoints[f.dataset.route].push({id:uid(),lat,lon,name:v.name.trim(),notes:v.notes.trim(),icon:'pin'});persist();closeModal();atlasSelected=routePoints().length-1;updateAtlasInfo();paintRoute();fitAtlasRoute();toast(at('pointAdded'))},true);
document.addEventListener('fullscreenchange',()=>{atlasMap?.invalidateSize()});
